$page_title='Student Dashboard'; $user=$_SESSION['username']; $academic=academic_context($conn,$user); $userSettings=get_user_settings($conn,$user,'student');
$stmt=$conn->prepare("SELECT COUNT(*) c FROM tbl_student_assignments WHERE username=?");$stmt->bind_param('s',$user);$stmt->execute();$assignments=(int)$stmt->get_result()->fetch_assoc()['c'];
$stmt=$conn->prepare("SELECT COUNT(*) c FROM tbl_leave_requests WHERE username=? AND status='Approved'");$stmt->bind_param('s',$user);$stmt->execute();$leaves=(int)$stmt->get_result()->fetch_assoc()['c'];
$events=$conn->query("SELECT * FROM tbl_events WHERE date>=CURDATE() ORDER BY date ASC LIMIT 5");
require '../includes/header.php';
